//! Static schema descriptor generated by `build.rs` from `schema/notability-ops.fbs`.

/// Scalar wire types.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Sc {
    Bool,
    U8,
    I8,
    U16,
    I16,
    U32,
    I32,
    U64,
    I64,
    F32,
    F64,
}

impl Sc {
    pub const fn size(self) -> usize {
        match self {
            Sc::Bool | Sc::U8 | Sc::I8 => 1,
            Sc::U16 | Sc::I16 => 2,
            Sc::U32 | Sc::I32 | Sc::F32 => 4,
            Sc::U64 | Sc::I64 | Sc::F64 => 8,
        }
    }
}

/// Vector element types.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum El {
    Scalar(Sc),
    Struct(usize),
    Table(usize),
    String,
}

/// Field types. Indices point into [`STRUCTS`], [`TABLES`] and [`UNIONS`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Ty {
    Scalar(Sc),
    Struct(usize),
    Table(usize),
    String,
    Union(usize),
    Vector(El),
}

#[derive(Debug)]
pub struct SField {
    pub name: &'static str,
    pub ty: Ty,
    pub offset: usize,
}

#[derive(Debug)]
pub struct StructDef {
    pub name: &'static str,
    pub size: usize,
    pub align: usize,
    pub fields: &'static [SField],
}

#[derive(Debug)]
pub struct TField {
    pub name: &'static str,
    pub slot: usize,
    pub ty: Ty,
}

#[derive(Debug)]
pub struct TableDef {
    pub name: &'static str,
    pub fields: &'static [TField],
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Variant {
    Table(usize),
    Struct(usize),
}

#[derive(Debug)]
pub struct UnionDef {
    pub name: &'static str,
    /// Variant `i` has wire tag `i + 1`; tag 0 is NONE.
    pub variants: &'static [(&'static str, Variant)],
}

include!(concat!(env!("OUT_DIR"), "/schema_desc.rs"));

/// Index of a table by name.
pub fn table(name: &str) -> Option<usize> {
    TABLES.iter().position(|t| t.name == name)
}

/// Index of a struct by name.
pub fn struct_index(name: &str) -> Option<usize> {
    STRUCTS.iter().position(|s| s.name == name)
}

/// Names of the 33 op payload kinds, in wire-tag order.
pub fn payload_kinds() -> impl Iterator<Item = &'static str> {
    UNIONS
        .iter()
        .find(|u| u.name == "PayloadUnion")
        .map(|u| u.variants.iter().map(|v| v.0))
        .into_iter()
        .flatten()
}
